namespace GearLab {
 public sealed class LoftLevel {public double Z;public CadLoop Outer;public List<CadLoop> Holes=new List<CadLoop>();}
 public sealed class ParametricLoft {
  public List<LoftLevel> Levels=new List<LoftLevel>();
  public SceneMesh Mesh(){var w=new MeshWriter();Func<CadLoop,CadLoop> cap=l=>l.Circle?CadLoop.Polygon(l.Sample(64)):l;SceneMesher.Cap(w,cap(Levels[0].Outer),Levels[0].Holes.Select(cap),Levels[0].Z,false);SceneMesher.Cap(w,cap(Levels.Last().Outer),Levels.Last().Holes.Select(cap),Levels.Last().Z,true);for(int i=0;i<Levels.Count-1;i++){var a=Levels[i];var b=Levels[i+1];Side(w,a.Outer,b.Outer,a.Z,b.Z,false);for(int j=0;j<a.Holes.Count;j++)Side(w,a.Holes[j],b.Holes[j],a.Z,b.Z,true);}return w.Finish();}
  static void Side(MeshWriter w,CadLoop la,CadLoop lb,double z0,double z1,bool hole){var a=la.Sample(64);var b=lb.Sample(64);if(a.Length!=b.Length)throw new Exception("Число точек сечений loft различается.");for(int i=0;i<a.Length;i++){int j=(i+1)%a.Length;var p=new Point3D(a[i].X,a[i].Y,z0);var q=new Point3D(a[j].X,a[j].Y,z0);var r=new Point3D(b[j].X,b[j].Y,z1);var s=new Point3D(b[i].X,b[i].Y,z1);Tri(w,p,hole?r:q,hole?q:r);Tri(w,p,hole?s:r,hole?r:s);}}
  static void Tri(MeshWriter w,Point3D a,Point3D b,Point3D c){var n=Vector3D.CrossProduct(b-a,c-a);if(n.LengthSquared<1e-16)return;n.Normalize();w.Triangle(a,b,c,n,n,n);}
 }
 public sealed class TransmissionMotion {public Vector3D Axis=new Vector3D(0,0,1);public Point3D Origin;public double Gain;public bool Linear,Orbit;public double OrbitRadius,OrbitGain,Initial;public Matrix3D At(double phase){if(Linear)return RobotMath.Translation(Axis.X*Gain*phase,Axis.Y*Gain*phase,Axis.Z*Gain*phase);var m=RobotMath.Translation(-Origin.X,-Origin.Y,-Origin.Z)*RobotMath.Rotation(Axis,Gain*phase*180/Math.PI)*RobotMath.Translation(Origin.X,Origin.Y,Origin.Z);if(Orbit)m.Translate(new Vector3D(OrbitRadius*(Math.Cos(Initial+phase*OrbitGain)-Math.Cos(Initial)),OrbitRadius*(Math.Sin(Initial+phase*OrbitGain)-Math.Sin(Initial)),0));return m;}}
