  static CadLoop C(double r){return CadLoop.Round(0,0,r);}public static CadLoop Rect(double x0,double y0,double x1,double y1){return CadLoop.Polygon(new[]{new PointF((float)x0,(float)y0),new PointF((float)x1,(float)y0),new PointF((float)x1,(float)y1),new PointF((float)x0,(float)y1)});}
  public static double[] Estimate(Result r){var p=r.P;double x=p.Module*(Math.Max(r.Z1,r.Z2)+2)/2+12,y=x,z=p.Thickness/2+12;if(p.Kind==5||p.Kind==10){x=Math.Max(x,Math.Max(p.Thickness*2,Math.PI*p.Module*8)/2+12);y=r.Engineering.Centre+r.Engineering.WormDiameter/2+p.Module+12;z=Math.Max(z,r.Engineering.WormDiameter/2+p.Module+12);}if(p.Kind==6||p.Kind==9){x=r.Engineering.ConeDistance+14;y=x+(p.Kind==9?Math.Abs(p.AxisOffset):0);z=x;}if(p.Kind==7)x=y=p.Radius+p.Roller/2+12;if(p.Kind==8)x=y=p.Module*(r.Z2+2.5)/2+12;if(p.Kind==11)x=y=p.Radius+12;if(p.Kind==12){x=p.RackLength/2+12;y=p.Module*p.Teeth/2+4*p.Module+12;}return new[]{-x,x,-y,y,-z,z};}
  public static CadPart Solid(CadAssembly a,string id,string label,string role,Color color,CadLoop outer,double z,double height,IEnumerable<CadLoop> holes=null,Matrix3D? placement=null){var q=new CadPart(id,label,role,color){Placement=placement??Matrix3D.Identity};q.Sections.Add(new CadSection(z,z+height,outer,holes));a.Parts.Add(q);return q;}
  static CadPart Gear(CadAssembly a,string id,int teeth,Parameters p,double width,double bore,Color col,Matrix3D place,double phase=0){return Solid(a,id,"Колесо z="+teeth,"gear",col,CadLoop.Polygon(Engine.Transform(Engine.Involute(teeth,p.Module,false,p.PressureAngle),0,0,phase)),-width/2,width,new[]{C(bore/2)},place);}
  static CadPart Loft(CadAssembly a,string id,string label,Color color,ParametricLoft loft,Matrix3D place){var q=Solid(a,id,label,"gear",color,loft.Levels[0].Outer,loft.Levels[0].Z,loft.Levels.Last().Z-loft.Levels[0].Z,loft.Levels[0].Holes,place);q.Loft=loft;q.MeshOverride=loft.Mesh();if(q.MeshOverride.SignedVolume()<=0)throw new Exception("Некорректный loft: "+label);return q;}
  static void Bind(Result r,CadPart q,double gain,Vector3D axis,Point3D origin,bool linear=false){r.TransmissionMotions[q.Id]=new TransmissionMotion{Gain=gain,Axis=axis,Origin=origin,Linear=linear};}
  static void Shaft(Result r,CadAssembly a,string id,double d,double lo,double hi,Matrix3D frame,double gain){var q=Solid(a,id,"Вал "+id,"shaft",Steel,C(d/2),lo,hi-lo,null,frame);Bind(r,q,gain,frame.Transform(new Vector3D(0,0,1)),frame.Transform(new Point3D()));}
  public static CadAssembly Build(Result r){var a=new CadAssembly();try{if(!r.Valid)throw new Exception("Исправьте параметры передачи.");var p=r.P;var e=r.Engineering;var z=new Vector3D(0,0,1);double t=p.Thickness;Matrix3D input=Matrix3D.Identity,output=Matrix3D.Identity;double inputLo=-t/2-15,inputHi=t/2+12,outputLo=inputLo,outputHi=inputHi;
   if(p.Kind==5||p.Kind==10){var wheel=Gear(a,"T_WHEEL",r.Z2,p,t,p.OutputShaft,Orange,output);Bind(r,wheel,e.SpeedGain,z,new Point3D());double length=Math.Max(t*2,Math.PI*p.Module*8),lead=Math.PI*p.Module*p.WormStarts;input=RobotMath.Rotation(new Vector3D(0,1,0),90)*RobotMath.Translation(0,e.Centre,0);var loft=new ParametricLoft();int slices=Math.Max(24,(int)Math.Ceiling(length/lead*24));for(int j=0;j<=slices;j++){double zz=-length/2+length*j/slices,root=e.WormDiameter/2-1.25*p.Module,glob=p.Kind==10?p.GloboidDepth*(1-Math.Pow(2*zz/length,2)):0;var pts=new List<PointF>();int n=p.WormStarts*32;for(int k=0;k<n;k++){double theta=Engine.Tau*k/n,u=(double)k/n*p.WormStarts,u1=u-Math.Floor(u),tooth=Math.Max(0,Math.Min(1,Math.Min((u1-.15)/.2,(.85-u1)/.2)));double radius=root-glob+2.25*p.Module*tooth,angle=theta+Engine.Tau*zz/lead;pts.Add(Engine.Polar(radius,angle));}loft.Levels.Add(new LoftLevel{Z=zz,Outer=CadLoop.Polygon(pts.ToArray()),Holes=new List<CadLoop>{C(p.Shaft/2)}});}var worm=Loft(a,"T_WORM","Червяк · компоновочная винтовая поверхность",Blue,loft,input);Bind(r,worm,1,new Vector3D(1,0,0),new Point3D(0,e.Centre,0));inputLo=-length/2-12;inputHi=length/2+12;}
   else if(p.Kind==6||p.Kind==9){input=Matrix3D.Identity;output=RobotMath.Rotation(new Vector3D(0,1,0),p.ShaftAngle)*RobotMath.Translation(0,p.Kind==9?p.AxisOffset:0,0);for(int k=0;k<2;k++){double cone=k==0?e.Cone1:e.Cone2,bore=k==0?p.Shaft:p.OutputShaft;int teeth=k==0?r.Z1:r.Z2;var loft=new ParametricLoft();var profile=Engine.Involute(teeth,p.Module,false,p.PressureAngle);for(int j=0;j<=4;j++){double s=(e.ConeDistance-t+t*j/4)/e.ConeDistance,zz=e.ConeDistance*s*Math.Cos(cone),angle=p.Kind==9?p.SpiralAngle*Math.PI/180*(1-s):0;var pts=Engine.Transform(profile.Select(v=>new PointF((float)(v.X*s),(float)(v.Y*s))).ToArray(),0,0,angle);NeedBore(pts,bore);loft.Levels.Add(new LoftLevel{Z=zz,Outer=CadLoop.Polygon(pts),Holes=new List<CadLoop>{C(bore/2)}});}var q=Loft(a,k==0?"T_PINION":"T_WHEEL","Коническое колесо z="+teeth,k==0?Blue:Orange,loft,k==0?input:output);Bind(r,q,k==0?1:e.SpeedGain,(k==0?input:output).Transform(z),(k==0?input:output).Transform(new Point3D()));if(k==0){inputLo=loft.Levels[0].Z;inputHi=loft.Levels.Last().Z+20;}else{outputLo=loft.Levels[0].Z;outputHi=loft.Levels.Last().Z+20;}}}
   else if(p.Kind==12){double radius=p.Module*p.Teeth/2;var pinion=Gear(a,"T_PINION",p.Teeth,p,t,p.Shaft,Blue,input,Math.PI/(2*p.Teeth));Bind(r,pinion,1,z,new Point3D());var pts=new List<PointF>();double pitch=Math.PI*p.Module,bottom=-radius-3.5*p.Module,root=-radius-1.25*p.Module,tip=-radius+p.Module;int count=(int)Math.Floor(p.RackLength/pitch);double len=count*pitch,x0=-len/2;pts.Add(new PointF((float)x0,(float)bottom));pts.Add(new PointF((float)(-x0),(float)bottom));pts.Add(new PointF((float)(-x0),(float)root));double slope=Math.Tan(p.PressureAngle*Math.PI/180),atip=pitch/4-p.Module*slope,aroot=pitch/4+1.25*p.Module*slope;for(int i=count-1;i>=0;i--){double cx=x0+(i+.5)*pitch;pts.Add(new PointF((float)(cx+aroot),(float)root));pts.Add(new PointF((float)(cx+atip),(float)tip));pts.Add(new PointF((float)(cx-atip),(float)tip));pts.Add(new PointF((float)(cx-aroot),(float)root));}pts.Add(new PointF((float)x0,(float)root));var rack=Solid(a,"T_RACK","Зубчатая рейка","gear",Orange,CadLoop.Polygon(pts.ToArray()),-t/2,t,null,RobotMath.Translation(p.RackPosition,0,0));Bind(r,rack,radius,new Vector3D(1,0,0),new Point3D(),true);output=RobotMath.Rotation(new Vector3D(0,1,0),90)*RobotMath.Translation(p.RackPosition,-radius-2.5*p.Module,0);outputLo=outputHi=0;
    for(int i=-1;i<=1;i+=2)Solid(a,"T_GUIDE"+i,"Направляющая рейки","fixed",Case,Rect(-len/2,-radius-4*p.Module,len/2,-radius+1.5*p.Module),i<0?-t/2-p.Wall-p.Clearance:t/2+p.Clearance,p.Wall);a.Notes.Add("Направляющие — открытый плоский шаблон. Ход ограничен в анимации; расчёт привода не учитывает трение направляющих.");}
