  static void NeedBore(PointF[] pts,double bore){if(pts.Min(v=>Math.Sqrt(v.X*v.X+v.Y*v.Y))<=bore/2+.3)throw new Exception("Вал не помещается в малом торце конуса.");}
  static void Magnetic(Result r,CadAssembly a){var p=r.P;double g=p.AirGap,m=p.MagnetThickness,ro=p.Radius,ri=ro-3*m-2*g,mod=ri+m+g;var z=new Vector3D(0,0,1);var core=Solid(a,"T_INNER_CORE","Внутренний магнитный ротор","shaft",Steel,C(ri),-p.Thickness/2,p.Thickness,new[]{C(p.Shaft/2)});Bind(r,core,1,z,new Point3D());var outer=Solid(a,"T_OUTER_CORE","Наружный магнитный ротор","shaft",Steel,C(ro+3),-p.Thickness/2,p.Thickness,new[]{C(ro)});Bind(r,outer,r.Engineering.SpeedGain,z,new Point3D());Action<int,double,double,string,double> segments=(n,r0,r1,prefix,gain)=>{for(int i=0;i<n;i++){double ca=Engine.Tau*i/n,da=Engine.Tau/n*.44;var pts=new List<PointF>();for(int k=0;k<=6;k++)pts.Add(Engine.Polar(r1,ca-da+2*da*k/6));for(int k=6;k>=0;k--)pts.Add(Engine.Polar(r0,ca-da+2*da*k/6));var q=Solid(a,prefix+i,prefix=="T_MOD"?"Ферромагнитный сегмент":"Магнит "+(i%2==0?"N":"S"),"magnet",prefix=="T_MOD"?Steel:i%2==0?Blue:Orange,CadLoop.Polygon(pts.ToArray()),-p.Thickness/2,p.Thickness);Bind(r,q,gain,z,new Point3D());}};segments(2*p.InnerPolePairs,ri,ri+m,"T_IMAG",1);segments(p.InnerPolePairs+p.OuterPolePairs,mod,mod+m,"T_MOD",0);segments(2*p.OuterPolePairs,ro-m,ro,"T_OMAG",r.Engineering.SpeedGain);Shaft(r,a,"T_INPUT_SHAFT",p.Shaft,-p.Thickness/2-18,p.Thickness/2,inputIdentity(),1);var cap=Solid(a,"T_OUTPUT_CAP","Выходной диск магнитного ротора","gear",Orange,C(ro+3),p.Thickness/2+p.Clearance,3,new[]{C(p.OutputShaft/2)});Bind(r,cap,r.Engineering.SpeedGain,z,new Point3D());Shaft(r,a,"T_OUTPUT_SHAFT",p.OutputShaft,p.Thickness/2+p.Clearance,p.Thickness/2+20,Matrix3D.Identity,r.Engineering.SpeedGain);}
